def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Power-law model for log10(|ID/A|) based on quadratic-square law."""
    K, Vt = parameters[0], parameters[1]
    log10_K = np.log10(K)
    return log10_K + 2 * np.log10(gate_voltage_abs - Vt) + 2 * np.log10(drain_voltage_abs - Vt)
